"""Run an independent check against a claim's current generated bytes."""
from __future__ import annotations

import os
import tempfile
from typing import Any

from . import kernel
from ._util import copy_into


def check(directory: str, check_file: str, command: str | None = None) -> dict[str, Any]:
    """Execute a caller supplied check in a disposable copy of the claim."""
    verified = kernel.verify(directory)
    if not verified["ok"]:
        raise kernel.ClaimError("claim identity mismatch")
    with tempfile.TemporaryDirectory(prefix="reticuli-heldout-") as room:
        parsed = kernel._materialize(directory, room)
        name = os.path.basename(check_file)
        copy_into(check_file, kernel._safe(room, name))
        result = kernel.run_gate(command or f"python3 {name}", room, parsed)
    return {"ok": result["status"] == "ok", "status": result["status"],
            "root": verified["root"], "quarantine": result.get("quarantine"),
            "stdout": result.get("stdout", ""), "stderr": result.get("stderr", "")}


heldout = check
